import{_ as o,o as n,c as a,af as s}from"./chunks/framework.B28LkSoM.js";const g=JSON.parse('{"title":"Python3 简介","description":"Python3 语言简介、设计哲学和应用领域","frontmatter":{"title":"Python3 简介","published":"2026-08-18T00:00:00.000Z","description":"Python3 语言简介、设计哲学和应用领域","tags":["Python"],"image":"https://img.tsh520.cn/file/blog/post-covers/python3-intro.webp","order":1,"date":"2026-08-18T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/Python学习笔记/01-Python3简介.md","filePath":"posts/学习文档/Python学习笔记/01-Python3简介.md"}'),e={name:"posts/学习文档/Python学习笔记/01-Python3简介.md"};function p(i,t,l,r,h,d){return n(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1787011200000"},[...t[0]||(t[0]=[s(`<h2 id="python3-简介" tabindex="-1">Python3 简介 <a class="header-anchor" href="#python3-简介" aria-label="Permalink to &quot;Python3 简介&quot;">​</a></h2><p>Python 是一个高层次的结合了解释性、编译性、互动性和面向对象的<strong>脚本语言。</strong></p><p>Python 的设计具有很强的可读性，相比其他语言经常使用英文关键字，其他语言的一些标点符号，它具有比其他语言更有特色语法结构。</p><ul><li><strong>Python 是一种解释型语言：</strong> 这意味着开发过程中没有了编译这个环节。</li><li><strong>Python 是交互式语言：</strong> 这意味着，您可以在一个 Python 提示符 &gt;&gt;&gt; 后直接执行代码。</li><li><strong>Python 是面向对象语言:</strong> 这意味着Python支持面向对象的风格或代码封装在对象的编程技术。</li><li><strong>Python 是初学者的语言：</strong> Python 对初级程序员而言，是一种伟大的语言，它支持广泛的应用程序开发，从简单的文字处理到 WWW 浏览器再到游戏。</li></ul><p><img src="https://img.tsh520.cn/file/blog/article/a700b5c8-d654-48f4-8c4c-63fc0070774f.webp" alt="Python 语言简介：主要特点、应用领域与程序运行流程"></p><hr><h2 id="python-特点" tabindex="-1">Python 特点 <a class="header-anchor" href="#python-特点" aria-label="Permalink to &quot;Python 特点&quot;">​</a></h2><ul><li><strong>1.易于学习：</strong> Python有相对较少的关键字，结构简单，和一个明确定义的语法，学习起来更加简单。</li><li><strong>2.易于阅读：</strong> Python代码定义的更清晰。</li><li><strong>3.易于维护：</strong> Python的成功在于它的源代码是相当容易维护的。</li><li><strong>4.一个广泛的标准库：</strong> Python的最大的优势之一是丰富的库，跨平台的，在UNIX，Windows和Macintosh兼容很好。</li><li><strong>5.互动模式：</strong> 互动模式的支持，您可以从终端输入执行代码并获得结果的语言，互动的测试和调试代码片断。</li><li><strong>6.可移植：</strong> 基于其开放源代码的特性，Python已经被移植（也就是使其工作）到许多平台。</li><li><strong>7.可扩展：</strong> 如果你需要一段运行很快的关键代码，或者是想要编写一些不愿开放的算法，你可以使用C或C++完成那部分程序，然后从你的Python程序中调用。</li><li><strong>8.数据库：</strong> Python提供所有主要的商业数据库的接口。</li><li><strong>9.GUI编程：</strong> Python支持GUI可以创建和移植到许多系统调用。</li><li><strong>10.可嵌入:</strong> 你可以将Python嵌入到C/C++程序，让你的程序的用户获得&quot;脚本化&quot;的能力。</li></ul><hr><h2 id="python3-下载" tabindex="-1">Python3 下载 <a class="header-anchor" href="#python3-下载" aria-label="Permalink to &quot;Python3 下载&quot;">​</a></h2><p>Python3 最新源码，二进制文档，新闻资讯等可以在 Python 的官网查看到。</p><p>Python 官网： <a href="https://www.python.org/" target="_blank" rel="noreferrer">https://www.python.org/</a></p><p><img src="https://img.tsh520.cn/file/blog/article/33d69961-710e-452e-9429-93cfdf2d3110.png" alt=""></p><p>Python3 提供了完整的中文文档： <a href="https://docs.python.org/zh-cn/3/" target="_blank" rel="noreferrer">https://docs.python.org/zh-cn/3/</a></p><hr><h2 id="python-安装" tabindex="-1">Python 安装 <a class="header-anchor" href="#python-安装" aria-label="Permalink to &quot;Python 安装&quot;">​</a></h2><p>以下为各平台对应的 Python 安装包下载地址：</p><p><img src="https://img.tsh520.cn/file/blog/article/9e11647a-cd0e-4117-8c49-976c3027aabe.png" alt=""></p><p><strong>Source Code</strong> 可用于 Linux 上的安装。</p><p>以下为不同平台上安装 Python3 的方法。</p><h3 id="window-平台安装-python" tabindex="-1">Window 平台安装 Python: <a class="header-anchor" href="#window-平台安装-python" aria-label="Permalink to &quot;Window 平台安装 Python:&quot;">​</a></h3><p>以下为在 Window 平台上安装 Python 的简单步骤。</p><p>打开 WEB 浏览器访问 <a href="https://www.python.org/downloads/windows/" target="_blank" rel="noreferrer">https://www.python.org/downloads/windows/</a> ：</p><p><img src="https://img.tsh520.cn/file/blog/article/1bf7d20f853bf2c4a8f03c03c864982f.png" alt=""></p><p>这些链接提供了不同类型的 Python 安装文件，适用于不同类型的 Windows 系统和使用情景：</p><ul><li><strong>Download Windows installer (64-bit)</strong> ：64 位 Windows 系统的安装程序。</li><li><strong>Download Windows installer (ARM64)</strong> ：适用于 ARM64 架构的 Windows 设备的安装程序。</li><li><strong>Download Windows embeddable package (64-bit)</strong> ：64 位 Windows 系统的嵌入式包，可用于嵌入到应用程序中。</li><li><strong>Download Windows embeddable package (32-bit)</strong> ：32 位 Windows 系统的嵌入式包，同样可用于嵌入到应用程序中。</li><li><strong>Download Windows embeddable package (ARM64)</strong> ：适用于 ARM64 架构的 Windows 设备的嵌入式包。</li><li><strong>Download Windows installer (32-bit)</strong> ：32 位 Windows 系统的安装程序。</li></ul><p>记得勾选 <strong>Add Python 3.6 to PATH</strong> 。</p><p><img src="https://img.tsh520.cn/file/blog/article/20180226150011548.png" alt=""></p><p>注意：如果没有勾选 <strong>Add Python3.6 to PATH</strong> 」，会导致命令行无法识别 python/python3 命令，需手动配置环境变量。</p><p>按 Win+R 键，输入 cmd 调出命令提示符，输入 python:</p><p><img src="https://img.tsh520.cn/file/blog/article/20170707155742110.png" alt=""></p><p>也可以在开始菜单中搜索 <strong>IDLE</strong> ：</p><p><img src="https://img.tsh520.cn/file/blog/article/460F6DFB-3BBF-4683-BEA0-23BE8DF021B0.jpg" alt=""></p><h3 id="unix-linux-平台安装-python3" tabindex="-1">Unix &amp; Linux 平台安装 Python3 <a class="header-anchor" href="#unix-linux-平台安装-python3" aria-label="Permalink to &quot;Unix &amp; Linux 平台安装 Python3&quot;">​</a></h3><p><strong>Linux 多数发行版自带 Python3</strong> ，若未安装或需要升级，可通过包管理器安装。</p><h4 id="源码安装" tabindex="-1">源码安装 <a class="header-anchor" href="#源码安装" aria-label="Permalink to &quot;源码安装&quot;">​</a></h4><p>以下为在 Unix &amp; Linux 平台上安装 Python 的简单步骤：</p><ul><li>打开 WEB 浏览器访问 <a href="https://www.python.org/downloads/source/" target="_blank" rel="noreferrer">https://www.python.org/downloads/source/</a></li><li>选择适用于 Unix/Linux 的源码压缩包。</li><li>下载及解压压缩包 <strong>Python-3.x.x.tgz</strong> ， <strong>3.x.x</strong> 为你下载的对应版本号。</li><li>如果你需要自定义一些选项修改 <em>Modules/Setup</em></li></ul><p>以 <strong>Python3.6.1</strong> 版本为例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># tar -zxvf Python-3.6.1.tgz</span></span>
<span class="line"><span># cd Python-3.6.1</span></span>
<span class="line"><span># ./configure</span></span>
<span class="line"><span># make &amp;&amp; make install</span></span></code></pre></div><h4 id="ubuntu-debian" tabindex="-1">Ubuntu/Debian <a class="header-anchor" href="#ubuntu-debian" aria-label="Permalink to &quot;Ubuntu/Debian&quot;">​</a></h4><p>打开终端，执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 更新软件源</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span># 安装Python3及pip3（Python包管理工具）</span></span>
<span class="line"><span>sudo apt install python3 python3-pip -y</span></span></code></pre></div><h4 id="centos-rhel" tabindex="-1">CentOS/RHEL <a class="header-anchor" href="#centos-rhel" aria-label="Permalink to &quot;CentOS/RHEL&quot;">​</a></h4><p>打开终端，执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># CentOS 7</span></span>
<span class="line"><span>sudo yum install epel-release -y</span></span>
<span class="line"><span>sudo yum install python3 python3-pip -y</span></span>
<span class="line"><span></span></span>
<span class="line"><span># CentOS 8/RHEL 8</span></span>
<span class="line"><span>sudo dnf install python3 python3-pip -y</span></span></code></pre></div><p>检查 Python3 是否正常可用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># python3 -V</span></span>
<span class="line"><span>Python 3.6.1</span></span></code></pre></div><h3 id="mac-平台安装-python" tabindex="-1">MAC 平台安装 Python: <a class="header-anchor" href="#mac-平台安装-python" aria-label="Permalink to &quot;MAC 平台安装 Python:&quot;">​</a></h3><p>MAC 系统都自带有 Python 环境，你可以在链接 <a href="https://www.python.org/downloads/mac-osx/" target="_blank" rel="noreferrer">https://www.python.org/downloads/mac-osx/</a> 上下载最新版安装。</p><p><img src="https://img.tsh520.cn/file/blog/article/aecef1c5-7bf6-4668-a6d7-6937a242817e.png" alt=""></p><p>你也可以参考源码安装的方式来安装。</p><h3 id="验证-python3-环境是否安装成功" tabindex="-1">验证 Python3 环境是否安装成功 <a class="header-anchor" href="#验证-python3-环境是否安装成功" aria-label="Permalink to &quot;验证 Python3 环境是否安装成功&quot;">​</a></h3><p>验证 Python3 版本打开命令提示符（Windows）或终端（macOS/Linux），执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 通用命令（推荐，所有系统兼容）</span></span>
<span class="line"><span>python3 --version</span></span>
<span class="line"><span># 补充：Windows系统若已配置PATH，也可执行</span></span>
<span class="line"><span>python --version</span></span></code></pre></div><p>若输出类似 Python 3.11.4 的信息，说明 Python3 安装成功。</p><p>验证 pip3（Python 包管理工具）pip3 是 Python3 默认的包管理工具，用于安装第三方库，验证命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 通用命令</span></span>
<span class="line"><span>pip3 --version</span></span>
<span class="line"><span># Windows补充命令</span></span>
<span class="line"><span>pip --version</span></span></code></pre></div><p>若输出类似 pip 23.1.2 from xxx (python 3.11) 的信息，说明 pip3 可用。</p><hr><h2 id="环境变量配置" tabindex="-1">环境变量配置 <a class="header-anchor" href="#环境变量配置" aria-label="Permalink to &quot;环境变量配置&quot;">​</a></h2><p>如果以上执行 python 命令执行成功，说明环境配置好了，不需要额外配置，这部分内容可以忽略。</p><p>程序可执行文件的存放目录常不在系统默认搜索路径中，而系统的 PATH 环境变量（Unix 区分大小写，Windows 不区分）正是用于存储可执行文件的搜索路径。</p><p>Mac OS 中若需在非默认目录引用 Python，需手动将 Python 安装目录添加到 PATH 中。</p><h3 id="在-unix-linux-设置环境变量" tabindex="-1">在 Unix/Linux 设置环境变量 <a class="header-anchor" href="#在-unix-linux-设置环境变量" aria-label="Permalink to &quot;在 Unix/Linux 设置环境变量&quot;">​</a></h3><p><strong>注：</strong> <strong>/usr/local/bin/python</strong> 为 Python 安装目录，需替换为你的实际路径。</p><p>bash shell（Linux）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/usr/local/bin/python&quot;</span></span></code></pre></div><p>csh shell：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setenv PATH &quot;$PATH:/usr/local/bin/python&quot;</span></span></code></pre></div><p>sh/ksh shell：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATH=&quot;$PATH:/usr/local/bin/python&quot;</span></span></code></pre></div><h3 id="在-windows-设置环境变量" tabindex="-1">在 Windows 设置环境变量 <a class="header-anchor" href="#在-windows-设置环境变量" aria-label="Permalink to &quot;在 Windows 设置环境变量&quot;">​</a></h3><p>若安装 Python3 时未勾选 Add Python.exe to PATH ，会导致命令行无法识别 python/python3 命令，需手动配置环境变量：</p><ul><li>找到 Python3 的安装路径（如D:\\Python311、C:\\Program Files\\Python311），同时找到其下的Scripts文件夹（路径如D:\\Python311\\Scripts，pip3 所在目录）。</li><li>右键「此电脑」→「属性」→「高级系统设置」→「环境变量」。</li><li>在「用户变量」或「系统变量」中找到 Path 变量，双击编辑。</li><li>点击「新建」，分别添加 Python3 的安装根路径和Scripts文件夹路径，点击「确定」保存所有配置。</li></ul><p><img src="https://img.tsh520.cn/file/blog/article/201209201707594792.png" alt=""></p><blockquote><p>更多详细配置内容参考： <a href="https://www.runoob.com/w3cnote/add-python-to-path-on-windows-11.html" target="_blank" rel="noreferrer">https://www.runoob.com/w3cnote/add-python-to-path-on-windows-11.html</a></p></blockquote><p>关闭原有命令提示符，重新打开后执行验证命令即可生效。</p><p>下面几个应用于 Python 的环境变量说明：</p><table tabindex="0"><thead><tr><th>环境变量名称</th><th>核心作用</th></tr></thead><tbody><tr><td><code>PATH</code></td><td>系统查找 Python 解释器及可执行文件的搜索路径</td></tr><tr><td><code>PYTHONPATH</code></td><td>Python 查找第三方库和自定义模块的搜索路径</td></tr><tr><td><code>PYTHONHOME</code></td><td>指定 Python 的安装根目录，告知解释器核心库/标准库存放位置</td></tr><tr><td><code>PYTHONSTARTUP</code></td><td>指定 Python 交互式解释器启动时自动执行的脚本文件路径</td></tr><tr><td><code>PYTHONCASEOK</code></td><td>Windows 专属，让 Python 导入模块时忽略大小写</td></tr><tr><td><code>PYTHONDONTWRITEBYTECODE</code></td><td>禁止 Python 运行时生成 <code>.pyc</code> / <code>.pyo</code> 字节码缓存文件</td></tr></tbody></table><hr><h2 id="运行-python" tabindex="-1">运行 Python <a class="header-anchor" href="#运行-python" aria-label="Permalink to &quot;运行 Python&quot;">​</a></h2><p>有三种方式可以运行 Python：</p><h3 id="_1、交互式解释器" tabindex="-1">1、交互式解释器： <a class="header-anchor" href="#_1、交互式解释器" aria-label="Permalink to &quot;1、交互式解释器：&quot;">​</a></h3><p>你可以通过命令行窗口进入 Python 并开始在交互式解释器中开始编写 Python 代码。</p><p>你可以在 Unix、DOS 或任何其他提供了命令行或者 shell 的系统进行 Python 编码工作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python</span></span></code></pre></div><p>以下为 Python 命令行参数：</p><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td>-d</td><td>启用调试模式，在代码解析和解释器运行时显示详细调试信息</td></tr><tr><td>-O</td><td>生成优化代码，编译脚本时生成.pyo 优化字节码文件（忽略断言语句等调试相关代码）</td></tr><tr><td>-OO</td><td>深度优化代码，生成.pyo 文件并移除代码中的所有文档字符串，进一步减小文件体积</td></tr><tr><td>-S</td><td>Python 启动时不自动引入 site 模块，即不加载查找 Python 模块路径的相关配置（如 site-packages 目录）</td></tr><tr><td>-V / --version</td><td>输出当前安装的 Python 版本号，直接退出解释器</td></tr><tr><td>-vv</td><td>输出详细的版本信息（包括编译环境、依赖库等额外信息）</td></tr><tr><td>-X</td><td>从 Python 1.6 版本之后，基于内建的异常（仅用于字符串类型）的用法已过时，该参数用于兼容旧版相关特性</td></tr><tr><td>-h / --help</td><td>查看所有 Python 命令行参数的完整帮助说明，直接退出解释器</td></tr><tr><td>-c cmd</td><td>直接在命令行中执行指定的 Python 代码片段（cmd 为字符串格式的代码），无需编写.py 脚本文件</td></tr><tr><td>-m module</td><td>以模块的形式运行指定的 Python 模块（如 pip、http.server 等），自动查找模块路径并执行</td></tr><tr><td>-i</td><td>执行完指定的 Python 脚本后，自动进入交互式解释器环境，便于后续调试和代码补充执行</td></tr><tr><td>-b</td><td>当遇到字节串（bytes）与字符串（str）不兼容的比较操作时，发出警告信息</td></tr><tr><td>-bb</td><td>当遇到字节串（bytes）与字符串（str）不兼容的比较操作时，直接抛出错误，终止程序运行</td></tr><tr><td>-u</td><td>禁用标准输出（stdout）和标准错误（stderr）的缓冲机制，实现日志或输出内容的实时打印</td></tr><tr><td>file</td><td>指定要执行的 Python 脚本文件路径（绝对路径或相对路径），解释器将加载并运行该文件中的代码</td></tr><tr><td>-q</td><td>进入交互式解释器时，隐藏欢迎信息，直接显示命令提示符</td></tr></tbody></table><h3 id="_2、命令行脚本" tabindex="-1">2、命令行脚本 <a class="header-anchor" href="#_2、命令行脚本" aria-label="Permalink to &quot;2、命令行脚本&quot;">​</a></h3><p>在你的应用程序中通过引入解释器可以在命令行中执行Python脚本，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python script.py</span></span></code></pre></div><p><strong>注意：</strong> 在执行脚本时，请检查脚本是否有可执行权限。</p><h3 id="_3、集成开发环境pycharm" tabindex="-1">3、集成开发环境PyCharm <a class="header-anchor" href="#_3、集成开发环境pycharm" aria-label="Permalink to &quot;3、集成开发环境PyCharm&quot;">​</a></h3><p>PyCharm 功能: 调试、语法高亮、Project管理、代码跳转、智能提示、自动完成、单元测试、版本控制……</p><p>PyCharm 下载地址: <a href="https://www.jetbrains.com/pycharm/download/" target="_blank" rel="noreferrer">https://www.jetbrains.com/pycharm/download/</a></p><p>PyCharm 安装地址： <a href="https://www.runoob.com/pycharm/pycharm-install.html" target="_blank" rel="noreferrer">https://www.runoob.com/pycharm/pycharm-install.html</a></p><p>PyCharm 界面：</p><p><img src="https://img.tsh520.cn/file/blog/article/newrunoob_1784096869537.png" alt=""></p><hr><h2 id="更多必备工具" tabindex="-1">更多必备工具 <a class="header-anchor" href="#更多必备工具" aria-label="Permalink to &quot;更多必备工具&quot;">​</a></h2><h3 id="anaconda-集成环境" tabindex="-1">Anaconda 集成环境 <a class="header-anchor" href="#anaconda-集成环境" aria-label="Permalink to &quot;Anaconda 集成环境&quot;">​</a></h3><p>一个 <strong>面向数据科学与机器学习</strong> 的 Python 集成发行版，内置：</p><ul><li>Python 解释器</li><li>常用数据科学库（NumPy / Pandas / Matplotlib 等）</li><li>环境与包管理工具 <code>conda</code></li></ul><p>相比 <code>pip</code> ， <strong>conda 更适合多环境切换</strong> ，在数据科学场景中更稳定。</p><p>安装与使用： <a href="https://www.runoob.com/python-qt/anaconda-tutorial.html" target="_blank" rel="noreferrer">Anaconda 教程</a></p><h3 id="uv-python-包与环境管理工具" tabindex="-1">uv Python 包与环境管理工具 <a class="header-anchor" href="#uv-python-包与环境管理工具" aria-label="Permalink to &quot;uv Python 包与环境管理工具&quot;">​</a></h3><p><strong>uv</strong> 是由 Astral 公司开发，基于 Rust 构建的高速 Python 工具链。</p><ul><li>高性能：相比 pip 提升 10~100 倍</li><li>依赖管理</li><li>虚拟环境管理</li><li>Python 版本管理</li></ul><p>可替代 <code>pip</code> 、 <code>virtualenv</code> 、 <code>pip-tools</code> 等工具的一体化方案</p><p>安装与使用： <a href="https://www.runoob.com/python3/uv-tutorial.html" target="_blank" rel="noreferrer">uv 教程</a></p><h3 id="jupyter-notebook-交互式计算工具" tabindex="-1">Jupyter Notebook 交互式计算工具 <a class="header-anchor" href="#jupyter-notebook-交互式计算工具" aria-label="Permalink to &quot;Jupyter Notebook 交互式计算工具&quot;">​</a></h3><p>一个 <strong>基于 Web 的交互式编程环境</strong> ，适用于学习、实验和数据分析。</p><ul><li>运行代码并实时查看结果</li><li>展示数据可视化图表</li><li>编写 Markdown 文档说明</li><li>支持数学公式（LaTeX）</li></ul><p>Notebook 文件为 JSON 格式，由多个 Cell 组成，可混合代码与文档内容。</p><p>安装与使用： <a href="https://www.runoob.com/jupyter-notebook/jupyter-notebook-tutorial.html" target="_blank" rel="noreferrer">Jupyter Notebook 教程</a></p><h2 id="vscode-配置" tabindex="-1">VScode 配置 <a class="header-anchor" href="#vscode-配置" aria-label="Permalink to &quot;VScode 配置&quot;">​</a></h2><h3 id="安装-vs-code" tabindex="-1">安装 VS Code <a class="header-anchor" href="#安装-vs-code" aria-label="Permalink to &quot;安装 VS Code&quot;">​</a></h3><p>VSCode 安装也很简单，打开官网 <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">https://code.visualstudio.com/</a> ，下载软件包，一步步安装即可，安装过程注意安装路径设置、环境变量默认自动添加到系统中，勾选以下所有选项：</p><p><img src="https://img.tsh520.cn/file/blog/article/RM04TZb.png" alt=""></p><p>VSCode 完整安装教程参考： <a href="https://www.runoob.com/vscode/vscode-tutorial.html" target="_blank" rel="noreferrer">https://www.runoob.com/vscode/vscode-tutorial.html</a></p><p>接着我们安装 Python 扩展：</p><p><img src="https://img.tsh520.cn/file/blog/article/de824f4aad280b93a3c54a5a088c81ca.png" alt=""></p><hr><h2 id="创建一个-python-代码文件" tabindex="-1">创建一个 Python 代码文件 <a class="header-anchor" href="#创建一个-python-代码文件" aria-label="Permalink to &quot;创建一个 Python 代码文件&quot;">​</a></h2><p>打开 VScode，然后点击新建文件：</p><p><img src="https://img.tsh520.cn/file/blog/article/vscode-py-1.jpeg" alt=""></p><p>点击选择语言：</p><p><img src="https://img.tsh520.cn/file/blog/article/vscode-py-2.jpg" alt=""></p><p>在搜索框输入 Python，选中 Python 选项：</p><p><img src="https://img.tsh520.cn/file/blog/article/vscode-py-3.jpg" alt=""></p><p>输入代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(&quot;Runoob&quot;)</span></span></code></pre></div><p>右击鼠标，选择在交互式窗口运行文件， <strong>如果有提示需要安装扩展，直接点安装即可(没有安装会一直显示在连接 Python 内核)：</strong></p><p><img src="https://img.tsh520.cn/file/blog/article/vscode-py-4.jpeg" alt=""></p><p>另外，我们也可以打开一个已存在的文件或目录（文件夹），比如我们打开一个 runoob-test，你也可以自己创建一个：</p><p><img src="https://img.tsh520.cn/file/blog/article/326906F8-C20B-4D76-AC86-FED6544B3DB5.jpeg" alt=""></p><p>然后我们创建一个 test.py 文件，点击下面新建文件图标，输入文件名 test.py：</p><p><img src="https://img.tsh520.cn/file/blog/article/86278531-3C46-4E05-BBE9-3E76CE82722A.jpg" alt=""></p><p><strong>注：</strong> runoob-test 里面包含了一个.vscode 文件夹，是一些配置信息，可以先不用管。</p><p>在 test.py 输入以下代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(&quot;Runoob&quot;)</span></span></code></pre></div><p>点击右上角绿色图标，即可运行：</p><p><img src="https://img.tsh520.cn/file/blog/article/438AF06B-6E02-42F0-9062-53337E8E90AD.jpg" alt=""></p><p>可以右击文件，选择&quot;在终端中运行 Python 文件&quot;：</p><p><img src="https://img.tsh520.cn/file/blog/article/16743E52-BE92-424B-AE7B-F9F602A44462.jpeg" alt=""></p><p>当然也可以在代码窗口上右击鼠标，选择&quot;在终端中运行 Python 文件&quot;。</p><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/posts/编程学习/python学习笔记/02-python3基础语法/">Python3 基础语法</a></li></ul><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><h3 id="一、知识回顾-读完直接做下面的实践题" tabindex="-1">一、知识回顾（读完直接做下面的实践题） <a class="header-anchor" href="#一、知识回顾-读完直接做下面的实践题" aria-label="Permalink to &quot;一、知识回顾（读完直接做下面的实践题）&quot;">​</a></h3><ol><li>Python 是一种高层次的、结合了<strong>解释性</strong>、<strong>编译性</strong>、<strong>互动性</strong>和<strong>面向对象</strong>的脚本语言。</li><li>Python 的四个定位：<strong>解释</strong>型语言（开发过程中没有编译环节）、<strong>交互</strong>式语言（在 <code>&gt;&gt;&gt;</code> 提示符后直接执行代码）、<strong>面向对象</strong>语言（支持把代码封装在对象里）、<strong>初学者</strong>的语言（从文字处理到浏览器再到游戏都能做）。</li><li>Python 官网是 <code>python.org</code>（域名）；Windows 安装时务必勾选 <strong>Add Python to PATH</strong>，否则命令行不认 <code>python</code> 命令；验证版本用 <code>python3 --version</code> 命令（Windows 也可用 <code>python --version</code>），验证包管理工具用 <code>pip3 --version</code> 命令（Windows 也可用 <code>pip --version</code>）。</li><li>Linux 源码安装的三步是 <code>./configure</code> → <code>make</code> → <code>make install</code>；Ubuntu/Debian 用 <strong>apt</strong> 安装（<code>sudo apt install python3 python3-pip -y</code>）、CentOS 8/RHEL 8 用 <strong>dnf</strong> 安装（<code>sudo dnf install python3 python3-pip -y</code>）；多数 Linux 发行版<strong>自带</strong> Python3。</li><li>环境变量：<code>PATH</code> 存可执行文件的搜索路径；<code>PYTHONPATH</code> 给 Python 找第三方库和自定义模块；<code>PYTHONHOME</code> 指定 Python 的安装根目录；<code>PYTHONSTARTUP</code> 指定交互式解释器启动时自动执行的脚本；<code>PYTHONCASEOK</code> 让导入模块时忽略大小写（Windows 专属）；<code>PYTHONDONTWRITEBYTECODE</code> 禁止生成 <code>.pyc</code> 字节码缓存文件。</li><li>运行 Python 的三种方式：<strong>交互式</strong>解释器、<strong>命令行</strong>脚本（<code>python script.py</code>）、集成开发环境 <strong>PyCharm</strong>；PyCharm 的功能包括调试、语法高亮、<strong>Project 管理</strong>、代码跳转、<strong>智能提示</strong>、<strong>自动完成</strong>、单元测试、版本控制等。</li><li>命令行参数：<code>-c cmd</code> 直接执行一段代码字符串；<code>-m module</code> 以模块方式运行；<code>-i</code> 执行完脚本后自动进入交互式环境；<code>-V</code>（<code>--version</code>）输出当前版本号；<code>-h</code>（<code>--help</code>）查看所有参数的完整帮助；<code>-u</code> 禁用输出缓冲、实现实时打印。</li><li>常用工具：面向数据科学的集成发行版 <strong>Anaconda</strong>（内置 <strong>conda</strong> 做环境与包管理，还自带 <strong>NumPy</strong>、<strong>Pandas</strong>、<strong>Matplotlib</strong> 等库）；基于 Rust 构建的高速工具链 <strong>uv</strong>（可替代 pip、virtualenv）；基于 Web 的交互式编程环境 <strong>Jupyter Notebook</strong>（文件是 JSON 格式，由多个 <strong>Cell</strong> 组成，支持 Markdown 与 LaTeX 公式）。</li><li>VSCode 里写 Python 需要先安装 <strong>Python</strong> 扩展；新建 <code>.py</code> 文件后可以右击选择&quot;在<strong>终端</strong>中运行 Python 文件&quot;，也可以点击右上角的<strong>绿色运行（▶）<strong>图标运行；如果一直显示&quot;在连接 Python 内核&quot;，说明扩展</strong>没装好</strong>。</li></ol><h3 id="二、概念自测" tabindex="-1">二、概念自测 <a class="header-anchor" href="#二、概念自测" aria-label="Permalink to &quot;二、概念自测&quot;">​</a></h3><ul><li><p>[ ] <strong>2-1</strong> &quot;解释型语言&quot;和&quot;编译型语言&quot;的区别是什么？为什么说 Python 开发过程中没有编译这个环节？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：从&quot;谁来把代码变成机器能跑的东西、什么时候变&quot;这个角度对比两种语言，再想 Python 是写完直接运行、还是要先单独编译一遍</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-1</strong> 编译型语言要先整体翻译成机器码、生成可执行文件，之后才能运行；解释型语言由解释器边读边执行，不需要提前生成可执行文件。Python 属于解释型（同时结合了编译性），所以开发时写完代码直接运行即可，中间没有单独的编译环节。</p></details></li><li><p>[ ] <strong>2-2</strong> 判断对错并说明理由：① Python 是编译型语言；② Windows 安装时没勾选 Add Python to PATH，也能在任意命令行窗口直接用 <code>python</code> 命令；③ Python 只能做数据分析；④ PyCharm 是一个集成开发环境。</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：四条里只有一条是对的：先分清&quot;解释型还是编译型&quot;，再想环境变量没配的后果，最后想 Python 的应用面和 PyCharm 的定位</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-2</strong> ① ❌ 错，Python 是解释型语言（&quot;结合了编译性&quot;不等于要你先编译）；② ❌ 错，没勾选就要手动配置环境变量，否则命令行识别不了 <code>python</code> / <code>python3</code>；③ ❌ 错，Python 可用于文字处理、Web、爬虫、游戏、GUI 等；④ ✅ 对。</p></details></li><li><p>[ ] <strong>2-3</strong> PATH 和 PYTHONPATH 都跟&quot;路径&quot;有关，它们各自负责找什么？没配好分别会出现什么现象？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：一个管&quot;系统到哪儿找可执行程序&quot;，一个管&quot;Python 到哪儿找模块&quot;；再分别想&quot;敲命令提示找不到&quot;和&quot;import 报找不到模块&quot;两种现象</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-3</strong> PATH 管的是&quot;系统到哪里找 Python 解释器和可执行文件&quot;（包括 pip 所在的 Scripts 目录），没配好的现象就是命令行敲 <code>python</code> / <code>pip</code> 提示找不到命令；PYTHONPATH 管的是&quot;Python 到哪里找第三方库和自定义模块&quot;，没配好会导致 <code>import</code> 自己写的模块时报找不到模块。</p></details></li><li><p>[ ] <strong>2-4</strong> 已经会写 Python 了，为什么还要认识 Anaconda、uv、Jupyter Notebook 这几个工具？它们各自解决什么问题？</p><details class="details custom-block"><summary>提示（先自己想，实在想不出再点开）</summary><p><strong>一级 · 思路</strong>：三个工具各对应一类麻烦——&quot;一次装齐科学计算环境&quot;&quot;装包快、环境好管&quot;&quot;边写边看结果&quot;，按这个分工各说一句</p></details><details class="details custom-block"><summary>参考答案（做完再点开）</summary><p><strong>2-4</strong> 三者都是&quot;让环境/工具更好用&quot;的辅助：</p><ul><li>Anaconda：面向数据科学与机器学习的集成发行版，一次装好解释器 + 常用科学计算库，自带 conda 做环境与包管理（多环境切换比 pip 稳）</li><li>uv：Rust 写的高速工具链，装包比 pip 快 10~100 倍，一套工具顶 pip / virtualenv / pip-tools</li><li>Jupyter Notebook：基于 Web 的交互式环境，可以边写代码边看结果，适合学习、实验和数据分析（文件是 JSON，由多个 Cell 组成）</li></ul></details></li></ul>`,155)])])}const u=o(e,[["render",p]]);export{g as __pageData,u as default};
